import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  const inner = new THREE.Group();
  root.add(inner);

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const ink = new THREE.Color(colors.ink ?? '#16161d');
  const paper = new THREE.Color(colors.paper ?? '#e8ecf2');
  const accent = new THREE.Color(colors.accent ?? '#ff2a38');
  const surface = new THREE.Color(colors.surface ?? '#0b0b10');

  const toVec3 = (c) => vec3(c.r, c.g, c.b);

  // --- Backdrop: engineered vertical gradient (surface -> ink) ---
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(toVec3(surface), toVec3(ink), smoothstep(0, 1, uv().y));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  inner.add(backdrop);

  // --- Accent bar: foreground depth element (signal red, < 10% frame) ---
  const barGeo = new THREE.PlaneGeometry(0.6, 0.035);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = toVec3(accent);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(0, -0.6, 0.4);
  inner.add(bar);

  // --- Feature card image plane (subject) ---
  const cardGeo = new THREE.PlaneGeometry(4.0, 2.5);
  const cardMat = new MeshBasicNodeMaterial();
  cardMat.colorNode = toVec3(paper);
  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0.15, 0);
  inner.add(card);

  // Async texture load onto the card plane
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.colorNode = null;
      cardMat.needsUpdate = true;
    });
  }

  // --- Collection headline via MSDF font atlas ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item.text) continue;
    const fontSize = item.typography?.fontSize ?? 96;
    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: '#e8ecf2',
      align: 'center',
    });
    textMesh.position.set(0, -0.95, 0.1);
    inner.add(textMesh);
  }

  // --- Entrance: rise-in (y +0.4 -> 0, power3.out) + weighted-settle (back.out) ---
  inner.position.y = 0.4;
  inner.scale.set(0.96, 0.96, 1);

  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'back.out(1.04)' }, 0);

  // --- Cleanup ---
  const geos = [backdropGeo, barGeo, cardGeo];
  const mats = [backdropMat, barMat, cardMat];

  root.userData.cleanup = () => {
    tl.kill();
    geos.forEach((g) => g && g.dispose());
    mats.forEach((m) => m && m.dispose());
  };

  root.userData.handlers = {};

  return root;
}
